DO $R$ BEGIN EXECUTE $Q235$CREATE OR REPLACE FUNCTION public.guard_security_profile_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_users integer;
BEGIN
  IF OLD.is_system THEN
    RAISE EXCEPTION 'System profiles cannot be deleted. Deactivate the profile instead.'
      USING ERRCODE = 'restrict_violation';
  END IF;

  SELECT count(*) INTO v_users
  FROM public.user_profiles
  WHERE profile_id = OLD.id;

  IF v_users > 0 THEN
    RAISE EXCEPTION 'Profile "%" has % user(s) assigned and cannot be deleted. Reassign those users or deactivate the profile instead.',
      OLD.name, v_users
      USING ERRCODE = 'restrict_violation';
  END IF;

  RETURN OLD;
END;
