DO $R$ BEGIN EXECUTE $Q239$CREATE OR REPLACE FUNCTION public.prevent_admin_sensitive_access()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- If user is admin and trying to access someone else's profile
  IF public.has_role(auth.uid(), 'admin'::public.app_role) AND auth.uid() != NEW.id THEN
    -- Prevent updates to sensitive fields
    IF OLD.hint_question IS DISTINCT FROM NEW.hint_question 
       OR OLD.hint_answer IS DISTINCT FROM NEW.hint_answer 
       OR OLD.recovery_email IS DISTINCT FROM NEW.recovery_email 
       OR OLD.phone_number IS DISTINCT FROM NEW.phone_number THEN
      RAISE EXCEPTION 'Admins cannot access or modify sensitive profile data';
    END IF;
  END IF;
  
  RETURN NEW;
END;
$function$$Q239$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema OR invalid_table_definition THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors3(stmt,err,state) VALUES (left($Q239$CREATE OR REPLACE FUNCTION public.prevent_admin_sensitive_access()
